/**
 * Rich failure telemetry channel.
 *
 * The command finalizer only receives (success, error) and derives a bounded
 * `error_code` from it. Argument-validation code paths know far more - which
 * specific rule failed and the human-readable message - so they deposit that
 * detail here for {@link trackCommand} to attach to the failed event.
 *
 * SCOPE NOTE: the captain waived the CLI-telemetry privacy-minimization
 * constraint, so failed events may carry the full human-readable error message
 * and (via the widened options allowlist) the offending option values. The one
 * HARD LINE that still applies: never deposit credentials, tokens, or API keys.
 * Validation messages here describe argument shapes only and never contain
 * secrets, so this module is safe by construction; do not route auth material
 * through it.
 */
export interface FailureContext {
    /**
     * Bounded validation-reason codes for the failed attempt (e.g.
     * `missing_project_id`, `invalid_props_shape`, `commander_missing_value`).
     * An attempt may fail for several reasons at once, so this is a list.
     */
    validationReasons?: string[];
    /** Full human-readable error message shown to the user. */
    errorMessage?: string;
    /**
     * Bounded auth-flow stage the attempt reached before failing (e.g.
     * `create_session`, `poll`, `save_config`). Set by the login/init flow so a
     * failed `login` event carries which stage broke instead of a flat exit code.
     */
    authStage?: string;
    /** Bounded auth-failure classification (e.g. `connection_error`, `timeout`). */
    authFailureCode?: string;
}
/** Record failure detail for the current command attempt (merges). */
export declare function recordFailureContext(ctx: FailureContext): void;
/** Read the accumulated failure detail. */
export declare function getFailureContext(): FailureContext;
/** Clear failure detail (primarily for tests / repeated in-process runs). */
export declare function resetFailureContext(): void;
/** Per-field length bound so a rich event stays a reasonable size. */
export declare const FAILURE_FIELD_MAX_LEN = 2000;
/**
 * Build the extra telemetry fields for a failed event from accumulated failure
 * context. Emits a comma-joined bounded `validation_reason` and the full (but
 * length-bounded) `error_message`. Returns an empty object when there is
 * nothing to add, so success events and non-validation failures are untouched.
 */
export declare function buildTelemetryFailureFields(ctx?: FailureContext, maxLen?: number): {
    validation_reason?: string;
    error_message?: string;
    auth_stage?: string;
    auth_failure_code?: string;
};
